2173→    State(state): State<Arc<AppState>>,
2174→    Path(job_id): Path<Uuid>,
2175→) -> Result<Json<ExportJobStatus>, AppError> {
2176→    let exports = state.export_jobs.read().await;
2177→    match exports.get(&job_id) {
