2183→async fn download_export(
2184→    State(state): State<Arc<AppState>>,
2185→    Path(job_id): Path<Uuid>,
2186→) -> Result<Response, AppError> {
2187→    let exports = state.export_jobs.read().await;
2188→    let entry = exports
2189→        .get(&job_id)
2190→        .ok_or_else(|| AppError::not_found("Export job not found"))?;
2191→
2192→    match entry.status.state {
2193→        JobState::Completed => {
2194→            let data = entry
2195→                .data
2196→                .as_ref()
2197→                .ok_or_else(|| AppError::internal("Export data missing"))?;
2198→            let disposition = format!(
2199→                "attachment; filename=\"{}-{}.{}\"",
2200→                entry.status.dataset, job_id, entry.status.format,
2201→            );
2202→            let mut response = (StatusCode::OK, data.body.clone()).into_response();
2203→            let headers = response.headers_mut();
2204→            headers.insert(
2205→                axum::http::header::CONTENT_TYPE,
2206→                axum::http::header::HeaderValue::from_static(data.content_type),
2207→            );
2208→            headers.insert(
2209→                axum::http::header::CONTENT_DISPOSITION,
2210→                axum::http::header::HeaderValue::from_str(&disposition)
2211→                    .map_err(|_| AppError::internal("Invalid disposition header"))?,
2212→            );
2213→            Ok(response)
2214→        }
2215→        JobState::Running | JobState::Pending => Err(AppError {
2216→            status: StatusCode::CONFLICT,
2217→            message: format!(
2218→                "Export job {} is still {}",
2219→                job_id,
2220→                if matches!(entry.status.state, JobState::Running) {
2221→                    "running"
2222→                } else {
2223→                    "pending"
2224→                }
2225→            ),
2226→        }),
2227→        JobState::Failed => Err(AppError::bad_request(format!(
2228→            "Export job {} failed: {}",
2229→            job_id,
2230→            entry.status.message.as_deref().unwrap_or("unknown error")
2231→        ))),
2232→    }
2233→}
