    let config = SinkConfig {
        sink_type: SinkType::Webhook,
        file_path: None,
        url: Some("ftp://badprotocol.com/hook".to_string()),
        headers: None,
        connection_string: None,
        table: None,
    };
    let err = validate_sink_config(&config).unwrap_err();
    assert!(err.message.contains("HTTP(S)"));
}

