    sqlx::query("UPDATE dataset_versions SET status = $2 WHERE id = $1")
        .bind(id)
        .bind(dataset_version_status_to_sql(
            &DatasetVersionStatus::Superseded,
        ))
        .execute(self.pool())
        .await?;
    Ok(())
}

