    State(state): State<Arc<AppState>>,
    Path(name): Path<String>,
) -> Result<Json<Vec<DatasetVersion>>, AppError> {
    validate_dataset_name(&name)?;
    let versions = state
        .repo
        .list_dataset_versions(&name)
        .await
        .map_err(AppError::internal)?;
    Ok(Json(versions))
}

async fn query_dataset_records(
    State(state): State<Arc<AppState>>,
    Path(name): Path<String>,
    Query(params): Query<DatasetQueryParams>,
) -> Result<Json<serde_json::Value>, AppError> {
    validate_dataset_name(&name)?;
    if !QUERYABLE_DATASETS.contains(&name.as_str()) {
        return Err(AppError::bad_request(format!(
            "Dataset '{}' is not queryable via this endpoint. Queryable datasets: {}",
            name,
            QUERYABLE_DATASETS.join(", ")
        )));
    }
    validate_date_range(params.time_start, params.time_end)?;
    let limit = clamp_limit(params.limit);
    let offset = clamp_offset(params.offset);
    let net = params.network.as_deref();

    let result = match name.as_str() {
        "token_transfers" => {
            let records = state
                .repo
                .query_token_transfers(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "native_balance_deltas" => {
            let records = state
                .repo
                .query_native_balance_deltas(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "decoded_events" => {
            let records = state
                .repo
                .query_decoded_events(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_fills" => {
            let records = state
                .repo
                .query_hl_fill_records(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "hl_funding" => {
            let records = state
                .repo
                .query_hl_funding_payments(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        "positions" => {
            let records = state
                .repo
                .query_hl_position_changes(
                    params.target_id,
                    net,
                    params.time_start,
                    params.time_end,
                    limit,
                    offset,
                )
                .await
                .map_err(AppError::internal)?;
            serde_json::to_value(&records).map_err(AppError::internal)?
        }
        _ => unreachable!("dataset name validated above"),
    };

    Ok(Json(result))
}

