            created_at: chrono::DateTime::from_timestamp(1700000000, 0).unwrap(),
        }];
        let bytes = serialize_to_jsonl(&records).unwrap();
        let output = String::from_utf8(bytes).unwrap();
        let lines: Vec<&str> = output.trim().split('\n').collect();
