) -> Result<Json<Network>, AppError> {
    let network = state
        .repo
        .get_network(&network_id)
        .await
        .map_err(AppError::internal)?
        .ok_or_else(|| AppError::not_found(format!("Network {} not found", network_id)))?;
    Ok(Json(network))
}

