        assert_eq!(json["transactions_per_chain"].as_array().unwrap().len(), 2);
        assert_eq!(json["transactions_per_chain"][0]["chain"], "ethereum");
        assert_eq!(json["transactions_per_chain"][0]["count"], 20);
    }

